import logging

from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import \
    Validator
from taf.fdsw.rc.schemas.FDSW21D.autoconnection_parameters_builder_21d import \
    AutoconnectionParametersBuilder21D

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoconnectionParametersBuilder22A(AutoconnectionParametersBuilder21D):
    def __init__(self, **kwargs):  # noqa: C901
        super(AutoconnectionParametersBuilder22A, self).__init__(**kwargs)

        if 'san_configuration' in kwargs:
            san_configuration = kwargs['san_configuration']

            self.certifcate_parameters.update(btsConfigurationOfSAN=Validator.validate_param(
                'san_configuration',
                san_configuration,
                (san_configuration in ['STATIC', 'DYNAMIC'])))

        if 'ee_cert_subject_name' in kwargs:
            ee_cert_subject_name = kwargs['ee_cert_subject_name']
            self.certifcate_parameters.update(eeSubjectName=ee_cert_subject_name)

        if 'ee_subject_alt_names' in kwargs:
            ee_subject_alt_names = kwargs['ee_subject_alt_names']
            self.certifcate_parameters.update(eeSubjectAltNames=ee_subject_alt_names)

        if 'bts_number_of_san' in kwargs:
            bts_number_of_san = kwargs['bts_number_of_san']
            self.certifcate_parameters.update(btsNumberOfSAN=bts_number_of_san)

        if 'ike_identity_to_use' in kwargs:
            ike_identity_to_use = kwargs['ike_identity_to_use']
            self.certifcate_parameters.update(ikeIdentityToUse=ike_identity_to_use)

        if 'san_sn_validation' in kwargs:
            san_sn_validation = kwargs['san_sn_validation']

            self.certifcate_parameters.update(actCertValidation=Validator.validate_param(
                'san_sn_validation',
                san_sn_validation,
                (san_sn_validation in ['ENABLED', 'DISABLED'])))

        if 'ee_ike_identity_index' in kwargs:
            ee_ike_identity_index = kwargs['ee_ike_identity_index']
            self.certifcate_parameters.update(ikeIdentityIndex=ee_ike_identity_index)

    def as_dict(self):
        attributes = super(AutoconnectionParametersBuilder22A, self).as_dict()
        self._move_vpn_gateway_ip(attributes)
        return attributes

    def _move_vpn_gateway_ip(self, attributes):
        if "certificateServerParameters" not in attributes:
            return
        else:
            if "vpnGatewayIpAddress" in attributes["certificateServerParameters"]:
                attributes["managementPlaneParameters"]["vpnGatewayIpAddress"] = attributes["certificateServerParameters"]["vpnGatewayIpAddress"]
                del (attributes["certificateServerParameters"]["vpnGatewayIpAddress"])
                if not attributes["certificateServerParameters"]:
                    del (attributes["certificateServerParameters"])
